// Local UX sandbox. Never accepted as a real wallet or redemption authority.
const pointsKey='anderzilla-karaca-demo-v1';
const pointRules={quiz:100,interests:25};
let pointClaims=[];
try{const stored=JSON.parse(localStorage.getItem(pointsKey)||'[]');if(Array.isArray(stored))pointClaims=[...new Set(stored.filter(x=>Object.hasOwn(pointRules,x)))];}catch{}
const pointBalance=()=>pointClaims.reduce((sum,id)=>sum+pointRules[id],0);
function awardPoints(id){if(!Object.hasOwn(pointRules,id)||pointClaims.includes(id))return false;pointClaims.push(id);try{localStorage.setItem(pointsKey,JSON.stringify(pointClaims));}catch{}return true;}
function resetPoints(){pointClaims=[];try{localStorage.removeItem(pointsKey);}catch{}}
function pointsTeaser(){return `<section class="points-banner"><div><p class="eyebrow">KARACA POINTS / ${L('MODO DEMO','DEMO MODE')}</p><h2>${L('Sua curiosidade ganha uma nova fase.','Your curiosity levels up.')}</h2><p>${L('Complete missões. Junte Karaca Points. Explore a futura Store Points.','Complete missions. Collect Karaca Points. Explore the future Store Points.')}</p></div><a class="button" href="#points">${pointBalance()} KP · ${L('Ver missões','View missions')} →</a></section>`;}
function pointsPage(){const missions=[{id:'quiz',ready:state.quizDone,title:L('Checkpoint da curiosidade','Curiosity checkpoint'),copy:L('Acerte as três perguntas do desafio. Uma recompensa por desafio, sem multiplicar ao repetir.','Answer all three challenge questions correctly. One reward per challenge, no replay farming.'),url:'#quiz'},{id:'interests',ready:state.interests.length>=3,title:L('Monte seu radar','Build your radar'),copy:L('Escolha pelo menos três interesses. Missão única de boas-vindas.','Choose at least three interests. A one-time welcome mission.'),url:'#profile'}];return `<div class="wrap subpage"><p class="eyebrow">KARACA! / PLAYER HUB</p><h1>${L('Descobrir é só o começo.','Discovery is just the beginning.')}</h1><div class="points-wallet"><div><span>${L('SALDO DEMONSTRATIVO','DEMO BALANCE')}</span><strong>${pointBalance()} <small>KP</small></strong></div><a class="button pink" href="#store">Store Points →</a></div><p class="notice">${L('Playtest: pontos locais, sem valor e sem resgate real. O programa real terá conta, validação de missões e catálogo com estoque confirmado. Este saldo não será migrado.','Playtest: local points, no value and no real redemption. The real program will use accounts, mission verification and confirmed inventory. This balance will not migrate.')}</p><h2>${L('Suas missões','Your missions')}</h2><div class="mission-grid">${missions.map(m=>`<article class="mission-card"><p class="eyebrow">+${pointRules[m.id]} KP · ${L('DEMONSTRAÇÃO','DEMO')}</p><h3>${m.title}</h3><p>${m.copy}</p>${pointClaims.includes(m.id)?`<span class="mission-done">✓ ${L('Recompensa recebida','Reward claimed')}</span>`:m.ready?`<button class="button" data-claim="${m.id}">${L('Receber pontos demo','Claim demo points')}</button>`:`<a class="button secondary" href="${m.url}">${L('Começar missão','Start mission')} →</a>`}</article>`).join('')}</div><h2>${L('Extrato de Karaca Points','Karaca Points activity')}</h2><ul class="points-ledger">${pointClaims.length?pointClaims.map(id=>`<li><span>${missions.find(m=>m.id===id).title}</span><strong>+${pointRules[id]} KP</strong></li>`).join(''):`<li>${L('Sua primeira missão começa agora.','Your first mission starts now.')}</li>`}</ul><p>${L('Na Store Points, só pontos conquistados no site. Sem comprar pontos, sem dinheiro no checkout.','Store Points uses only points earned on the site. No points purchases and no cash checkout.')}</p></div>`;}
function storePage(){return `<div class="wrap subpage"><p class="eyebrow">KARACA! / STORE POINTS</p><h1>${L('Bons loots. Só com pontos.','Great loot. Points only.')}</h1><p class="lede">${L('O destino dos seus Karaca Points: assinaturas, produtos digitais e gadgets fornecidos pelo AnderZilla. Catálogo em preparação.','The destination for your Karaca Points: subscriptions, digital products and gadgets supplied by AnderZilla. Catalog in preparation.')}</p><div class="points-wallet"><div><span>${L('SALDO DEMONSTRATIVO','DEMO BALANCE')}</span><strong>${pointBalance()} <small>KP</small></strong></div><a class="button" href="#points">${L('Ganhar pontos','Earn points')} →</a></div><div class="mission-grid reward-concepts">${[[L('Assinaturas','Subscriptions'),'◇'],[L('Produtos digitais','Digital products'),'⌘'],['Gadgets','✦']].map(([name,glyph])=>`<article class="mission-card"><span class="reward-glyph" aria-hidden="true">${glyph}</span><p class="eyebrow">${L('CATEGORIA PLANEJADA','PLANNED CATEGORY')}</p><h2>${name}</h2><p>${L('Produtos, custo em KP e disponibilidade serão anunciados após confirmação do estoque.','Products, KP cost and availability will be announced after inventory confirmation.')}</p><button class="button secondary" disabled>${L('Em preparação','In preparation')}</button></article>`).join('')}</div><section class="redemption-steps"><h2>${L('Do checkpoint ao resgate','From checkpoint to redemption')}</h2><ol><li>${L('Ganhe pontos em missões verificadas.','Earn points through verified missions.')}</li><li>${L('Escolha um item disponível e confira região, entrega e custo em KP.','Choose an available item and check region, delivery and KP cost.')}</li><li>${L('Confirme o resgate. Os pontos e o estoque ficam reservados durante a análise.','Confirm redemption. Points and stock are reserved during review.')}</li><li>${L('Acompanhe a entrega na sua conta. Se o pedido for cancelado, a reserva é devolvida.','Track delivery in your account. If cancelled, the reservation is released.')}</li></ol><p class="notice">${L('Nenhum produto disponível para resgate ainda. Pontos desta prévia são demonstrativos. Não há promessa de prêmio, conversão em dinheiro ou assinatura recorrente.','No products are redeemable yet. Preview points are demonstrations. No prize, cash conversion or recurring subscription is promised.')}</p></section></div>`;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-claim]');if(!button)return;const id=button.dataset.claim;const eligible=id==='quiz'?state.quizDone:id==='interests'&&state.interests.length>=3;if(eligible&&awardPoints(id)){render();toast(L('Karaca! Pontos demo recebidos.','Karaca! Demo points claimed.'));}});
